appearances.css:
.app{display:flex;flex-wrap:wrap;align-content:flex-start;gap:4px;padding:6px;font-size:9px;border-radius:4px;--pk-wave-h:64px}
.app>*{min-width:0}
button,select,input{padding:2px 5px;font-size:9px;border-radius:3px}
.row{margin:0;gap:4px;flex:1 1 100%;align-items:center}
.row .control{display:block;border:0;padding:0;flex:0 0 auto}
.row .control>span{display:none}
.row select,.row input[type=text],.row button{height:24px}
.row input[type=text]{flex:1 1 60px;width:auto}
.pads{flex:1 1 100%;grid-template-columns:repeat(8,minmax(0,1fr));gap:3px}
.pads button{min-height:28px;padding:2px 3px;font-size:8px;line-height:1.25;white-space:pre;overflow:hidden;text-overflow:ellipsis;text-align:left;border-radius:3px}
h3{flex:1 1 100%;margin:2px 0 0;font-size:9px;line-height:1.2}
.app>input[type=text]{flex:1 1 110px;width:auto;height:24px}
.app>input[type=file]{flex:2 1 160px;width:auto;height:24px;padding:0 3px;font-size:9px;line-height:20px}
input[type=file]::file-selector-button{font:inherit;padding:1px 5px;margin:0 4px 0 0;border-radius:3px}
canvas{flex:1 1 100%;width:100%;border-radius:3px}
.grid{display:grid;gap:3px 0;align-content:start;padding:3px 4px 4px;border:1px solid var(--line,#344953);border-radius:3px;flex:1 1 100%}
.grid:nth-of-type(4){grid-template-columns:repeat(9,minmax(0,1fr))}
.grid:nth-of-type(5){flex:0 0 auto;grid-template-columns:repeat(4,52px)}
.grid .control{display:grid;grid-template-columns:minmax(0,1fr);justify-items:center;align-content:start;gap:0;border:0;padding:0;min-width:0}
.grid .control>span:not(.kn){order:3;font-size:7px;line-height:1.1;text-align:center;max-width:100%;letter-spacing:-.05em;overflow-wrap:anywhere;padding:0}
.grid output{order:2;font:8px/1.1 monospace;text-align:center;white-space:nowrap}
.grid .kn{order:1;width:28px!important;height:28px!important;justify-self:center!important}
.grid .kn svg{width:100%;height:100%}
.grid .control:has(select){grid-column:span 2;align-self:center;padding:0 3px}
.grid .control:has(select) select{order:1;width:100%;height:24px;text-overflow:ellipsis}
.row:nth-of-type(6){flex:1 1 200px;gap:3px;align-content:flex-start}
.row:nth-of-type(6) button{padding:2px 4px}
.row:nth-of-type(6) .control{flex:1 1 90px}
.row:nth-of-type(6) .control select{width:100%}
.app>input[type=file]:nth-last-of-type(1){flex:1 1 150px}
p{margin:0;font-size:8px;line-height:1.2;flex:1 1 150px}
.row:nth-of-type(3){gap:3px}
.row:nth-of-type(3) button{padding:2px 4px;font-size:8.5px}
